//! Build-pipeline tests: assert the IR table generated by build.rs from the
//! vendored spec has the expected shape.

#![allow(clippy::unwrap_used, clippy::expect_used)]

use engine::{BodyMode, ParamType};
use otl::ops;
use serde_json::Value;

/// Look up an operation in the BUILT-IN table.
///
/// Not `ops::find`, which prefers a synced spec cache if the machine has
/// one: this file asserts what `build.rs` compiled from the vendored spec,
/// so it must not depend on the developer's cache directory.
fn builtin(name: &str) -> Option<&'static engine::OpSpec> {
    ops::OPS.iter().find(|op| op.name == name)
}

/// The vendored spec, parsed fresh so tests compare against the source of
/// truth rather than a hardcoded operation count.
fn vendored_spec() -> Value {
    serde_json::from_str(include_str!("../spec/spec3.json")).unwrap()
}

/// Operation names (path minus leading `/`) of every POST path in the spec.
fn spec_operation_names(spec: &Value) -> Vec<String> {
    spec["paths"]
        .as_object()
        .unwrap()
        .iter()
        .filter(|(_, item)| item.get("post").is_some())
        .map(|(path, _)| path.trim_start_matches('/').to_string())
        .collect()
}

#[test]
fn table_compiles_every_spec_operation() {
    let spec = vendored_spec();
    let expected = spec_operation_names(&spec);
    // Sanity: the vendored spec is the full API.
    assert!(
        expected.len() > 100,
        "vendored spec unexpectedly small: {} ops",
        expected.len()
    );
    assert_eq!(
        ops::OPS.len(),
        expected.len(),
        "IR table op count != spec op count"
    );
    for name in &expected {
        assert!(builtin(name).is_some(), "{name} missing from IR table");
    }
}

#[test]
fn table_spans_multiple_resources() {
    for name in [
        "documents.info",
        "documents.search",
        "collections.list",
        "users.invite",
        "shares.create",
        "auth.info",
        "attachments.create",
    ] {
        assert!(builtin(name).is_some(), "{name} missing");
    }
}

#[test]
fn every_op_has_api_prefixed_path() {
    for op in ops::OPS {
        // The Outline URL convention (`/api/...`) is applied by the otl
        // build pipeline; the engine joins base + path verbatim.
        assert_eq!(op.path.as_ref(), format!("/api/{}", op.name));
    }
}

#[test]
fn every_op_has_a_single_line_summary() {
    for op in ops::OPS {
        assert!(
            !op.summary.trim().is_empty(),
            "{} has an empty summary",
            op.name
        );
        assert!(
            !op.summary.contains('\n'),
            "{} summary spans lines",
            op.name
        );
    }
}

#[test]
fn documents_info_has_string_id_param() {
    let op = builtin("documents.info").unwrap();
    let param = op.param("id").unwrap();
    assert_eq!(param.ty, ParamType::String);
}

#[test]
fn documents_search_expands_all_of_params() {
    // `documents.search` composes its schema via allOf + $ref (Pagination);
    // the build pipeline must expand both.
    let op = builtin("documents.search").unwrap();
    let query = op.param("query").unwrap();
    assert_eq!(query.ty, ParamType::String);
    // From the referenced Pagination component schema.
    let limit = op.param("limit").unwrap();
    assert_eq!(limit.ty, ParamType::Number);
    let offset = op.param("offset").unwrap();
    assert_eq!(offset.ty, ParamType::Number);
    // Array parameter falls back to Json.
    let filters = op.param("filters").unwrap();
    assert_eq!(filters.ty, ParamType::Json);
}

#[test]
fn documents_list_expands_multiple_refs() {
    // `documents.list` composes Pagination + Sorting + inline properties.
    let op = builtin("documents.list").unwrap();
    assert_eq!(op.param("sort").unwrap().ty, ParamType::String);
    assert_eq!(op.param("direction").unwrap().ty, ParamType::String);
    assert_eq!(op.param("limit").unwrap().ty, ParamType::Number);
    assert!(op.param("collectionId").is_some());
}

#[test]
fn no_all_of_op_has_an_empty_param_table() {
    // Regression guard for the allOf bug: these ops declare params only
    // through allOf and must not end up with empty tables.
    for name in [
        "documents.search",
        "documents.search_titles",
        "documents.list",
        "documents.drafts",
        "documents.viewed",
        "documents.archived",
        "documents.deleted",
        "documents.answerQuestion",
        "documents.group_memberships",
        "users.list",
        "events.list",
    ] {
        let op = builtin(name).unwrap();
        assert!(!op.params.is_empty(), "{name} has an empty param table");
    }
}

#[test]
fn scalar_integer_and_boolean_params_are_typed() {
    let op = builtin("documents.update").unwrap();
    assert_eq!(op.param("lastRevision").unwrap().ty, ParamType::Integer);
    assert_eq!(op.param("publish").unwrap().ty, ParamType::Boolean);
    // Objects and arrays stay Json (complex; k=v must be rejected).
    assert_eq!(op.param("preferences").unwrap().ty, ParamType::Json);
    assert_eq!(op.param("dataAttributes").unwrap().ty, ParamType::Json);
}

#[test]
fn ref_and_all_of_wrapped_scalars_resolve_to_scalar_types() {
    // documents.update `editMode` is `$ref -> TextEditMode` (string enum).
    let edit_mode = builtin("documents.update").unwrap().param("editMode");
    assert_eq!(edit_mode.unwrap().ty, ParamType::String);
    // users.list `role` is `allOf -> $ref UserRole` (string enum).
    let role = builtin("users.list").unwrap().param("role");
    assert_eq!(role.unwrap().ty, ParamType::String);
}

#[test]
fn root_level_one_of_marks_the_operation_raw_body_only() {
    // shares.create constrains via a root-level oneOf(required: documentId
    // | required: collectionId): exactly one of the two must be present, a
    // rule key=value assembly cannot express. The operation is therefore
    // compiled as raw-body-only, with both properties still described.
    let op = builtin("shares.create").unwrap();
    assert_eq!(op.body_mode, BodyMode::RawJsonOnly);
    assert_eq!(op.param("documentId").unwrap().ty, ParamType::String);
    assert_eq!(op.param("collectionId").unwrap().ty, ParamType::String);
}

#[test]
fn only_root_level_unions_are_raw_body_only() {
    // A oneOf nested inside a property (e.g. documents.list `filters`)
    // must not make the whole operation raw-body-only.
    assert_eq!(
        builtin("documents.list").unwrap().body_mode,
        BodyMode::KeyValue
    );
    let raw_only: Vec<&str> = ops::OPS
        .iter()
        .filter(|op| op.body_mode == BodyMode::RawJsonOnly)
        .map(|op| op.name.as_ref())
        .collect();
    assert_eq!(raw_only, vec!["shares.create"]);
}

#[test]
fn non_json_request_bodies_are_marked_unsupported() {
    // documents.import only accepts multipart/form-data, which the generic
    // engine cannot assemble; it must be marked, not silently callable.
    let op = builtin("documents.import").unwrap();
    assert_eq!(op.body_mode, BodyMode::Unsupported);
    assert_eq!(op.content_type.as_ref(), "multipart/form-data");
    assert!(op.params.is_empty(), "no params for an unsupported body");

    let unsupported: Vec<&str> = ops::OPS
        .iter()
        .filter(|op| op.body_mode == BodyMode::Unsupported)
        .map(|op| op.name.as_ref())
        .collect();
    assert_eq!(unsupported, vec!["documents.import"]);
}

#[test]
fn json_and_bodyless_operations_carry_the_expected_content_type() {
    for op in ops::OPS {
        match op.body_mode {
            BodyMode::Unsupported => assert_ne!(op.content_type.as_ref(), "application/json"),
            _ => assert!(
                op.content_type.as_ref() == "application/json" || op.content_type.is_empty(),
                "{} has content type {:?}",
                op.name,
                op.content_type
            ),
        }
    }
    // Operations without any request body carry no content type.
    assert!(builtin("auth.info").unwrap().content_type.is_empty());
}

#[test]
fn enum_variants_are_compiled_into_the_ir() {
    let op = builtin("accessRequests.approve").unwrap();
    let permission = op.param("permission").unwrap();
    assert_eq!(
        permission.enum_values.as_ref(),
        ["read", "read_write", "admin"]
    );
    // Enums reached through allOf/$ref wrappers are compiled too.
    let create = builtin("collections.create").unwrap();
    assert_eq!(
        create.param("permission").unwrap().enum_values.as_ref(),
        ["read", "read_write"]
    );
    // A plain string param has no enum constraint.
    assert!(op.param("id").unwrap().enum_values.is_empty());
}

#[test]
fn nullable_params_are_flagged() {
    let op = builtin("documents.update").unwrap();
    assert!(op.param("collectionId").unwrap().nullable);
    assert!(op.param("icon").unwrap().nullable);
    assert!(!op.param("id").unwrap().nullable);
    assert!(!op.param("title").unwrap().nullable);
}

#[test]
fn formats_are_compiled_into_the_ir() {
    let approve = builtin("accessRequests.approve").unwrap();
    assert_eq!(approve.param("id").unwrap().format.as_ref(), "uuid");
    assert_eq!(
        builtin("documents.insights")
            .unwrap()
            .param("startDate")
            .unwrap()
            .format
            .as_ref(),
        "date-time"
    );
    assert_eq!(
        builtin("shares.update")
            .unwrap()
            .param("iconUrl")
            .unwrap()
            .format
            .as_ref(),
        "uri"
    );
    // A vendor-specific format is carried but not enforced at runtime.
    assert_eq!(
        builtin("users.update")
            .unwrap()
            .param("language")
            .unwrap()
            .format
            .as_ref(),
        "BCP47"
    );
    // An unconstrained string carries no format.
    assert!(builtin("documents.update")
        .unwrap()
        .param("title")
        .unwrap()
        .format
        .is_empty());
}

#[test]
fn pattern_constraints_are_deliberately_not_compiled() {
    // templates.update `color` declares `pattern: ^#[0-9A-Fa-f]{6}$`.
    // Validating it would need a regex engine (about a megabyte of binary
    // for the two pattern constraints in the whole spec), so the value is
    // left for the server to reject. This test documents that choice.
    let color = builtin("templates.update").unwrap().param("color").unwrap();
    assert!(color.format.is_empty(), "no format facet on color");
    assert_eq!(color.ty, ParamType::String);
    assert!(color.nullable);
}

#[test]
fn numeric_bounds_are_compiled_into_the_ir() {
    let size = builtin("attachments.create")
        .unwrap()
        .param("size")
        .unwrap();
    assert_eq!(size.minimum, Some(0.0));
    assert_eq!(size.maximum, None);
    let revision = builtin("documents.update")
        .unwrap()
        .param("lastRevision")
        .unwrap();
    assert_eq!(revision.minimum, Some(0.0));
    // An unbounded number carries no bounds.
    let limit = builtin("documents.search").unwrap().param("limit").unwrap();
    assert_eq!((limit.minimum, limit.maximum), (None, None));
}

#[test]
fn required_params_are_marked() {
    // Upstream spec marks `id` as required for documents.update.
    let op = builtin("documents.update").unwrap();
    let param = op.param("id").unwrap();
    assert!(param.required);
    // users.invite requires the complex `invites` parameter.
    let invites = builtin("users.invite").unwrap().param("invites").unwrap();
    assert!(invites.required);
    assert_eq!(invites.ty, ParamType::Json);
}

#[test]
fn ops_without_request_body_have_empty_param_tables() {
    for name in ["auth.info", "auth.config"] {
        let op = builtin(name).unwrap();
        assert!(op.params.is_empty(), "{name} should have no params");
    }
}

#[test]
fn find_returns_none_for_unknown_operation() {
    assert!(builtin("documents.doesNotExist").is_none());
}

// ---------------------------------------------------------------------------
// Response-shape descriptors compiled into the IR.
// ---------------------------------------------------------------------------

/// Field names of an operation's compiled response shape, in order.
fn response_field_names(op: &engine::OpSpec) -> Vec<&str> {
    op.response_fields
        .iter()
        .map(|field| field.name.as_ref())
        .collect()
}

#[test]
fn response_fields_are_compiled_for_list_and_single_operations() {
    // A list response (`data` is an array of items) and a single-object
    // response must both yield the item's fields.
    for name in ["documents.list", "documents.info"] {
        let op = ops::find(name).unwrap();
        let fields = response_field_names(op);
        assert!(fields.contains(&"id"), "{name}: {fields:?}");
        assert!(fields.contains(&"title"), "{name}: {fields:?}");
        assert!(fields.contains(&"updatedAt"), "{name}: {fields:?}");
    }
}

#[test]
fn response_fields_keep_the_specs_declaration_order() {
    // Declaration order is load-bearing for column selection: the renderer
    // ranks ties by it, so an alphabetically sorted table would pick the
    // document body over its title.
    let fields = response_field_names(ops::find("documents.list").unwrap());
    let position = |name: &str| fields.iter().position(|f| *f == name);
    assert_eq!(position("id"), Some(0), "{fields:?}");
    assert!(position("title") < position("text"), "{fields:?}");
    assert!(position("createdAt") < position("updatedAt"), "{fields:?}");
    // Collection declares its read-only `url` before the writable `name`.
    let collections = response_field_names(ops::find("collections.list").unwrap());
    let cpos = |name: &str| collections.iter().position(|f| *f == name);
    assert!(cpos("url") < cpos("name"), "{collections:?}");
}

#[test]
fn response_field_facets_are_compiled() {
    let op = ops::find("documents.list").unwrap();
    let field = |name: &str| {
        op.response_fields
            .iter()
            .find(|f| f.name == name)
            .unwrap_or_else(|| panic!("{name} missing from {:?}", response_field_names(op)))
    };
    let id = field("id");
    assert_eq!(id.ty, ParamType::String);
    assert_eq!(id.format.as_ref(), "uuid");
    assert!(!id.nullable);
    assert!(id.read_only, "`id` is readOnly in the spec");

    let title = field("title");
    assert_eq!(title.format.as_ref(), "");
    assert!(!title.nullable);
    assert!(!title.read_only, "`title` is writable");

    assert_eq!(field("updatedAt").format.as_ref(), "date-time");
    assert!(field("collectionId").nullable);
    // Containers stay Json so a generic renderer can never make them cells.
    assert_eq!(field("tasks").ty, ParamType::Json);
    assert_eq!(field("createdBy").ty, ParamType::Json);
    // `url` is derived, `name`-like fields are not.
    assert!(field("url").read_only);
}

#[test]
fn operations_without_a_described_response_have_no_response_fields() {
    // `documents.delete` documents only an empty success response.
    let op = ops::find("documents.delete").unwrap();
    assert!(
        op.response_fields.is_empty(),
        "{:?}",
        response_field_names(op)
    );
}

#[test]
fn most_operations_carry_a_compiled_response_shape() {
    // Guard against a silent regression that empties the whole column
    // source (e.g. a pointer typo): the vendored spec describes a response
    // payload for the large majority of its operations.
    let described = ops::OPS
        .iter()
        .filter(|op| !op.response_fields.is_empty())
        .count();
    assert!(
        described * 2 > ops::OPS.len(),
        "only {described} of {} operations have response fields",
        ops::OPS.len()
    );
}

#[test]
fn response_fields_never_repeat_a_name() {
    for op in ops::OPS {
        let mut names = response_field_names(op);
        let total = names.len();
        names.sort_unstable();
        names.dedup();
        assert_eq!(
            names.len(),
            total,
            "{} has duplicate response fields",
            op.name
        );
    }
}
